  function stars(score) {
    const box = el("div", "d2-stars");
    const half = score == null ? 0 : Math.ceil(Math.max(0, Math.min(100, score)) / 10);
    box.setAttribute("aria-label", `${half / 2} of 5 stars`);
    for (let i = 0; i < 5; i++) {
      const filled = half >= 2 * (i + 1) ? "full" : half === 2 * i + 1 ? "half" : "empty";
      box.appendChild(el("span", `d2-star ${filled}`, "\u2605"));
    }
    return box;
  }
